{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2173-04-27 02:00:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. You're in the hospital because of trouble breathing. Can you tell me what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2173-04-27 02:02:00",
      "speaker": "Patient",
      "text": "Yes, I’ve had shortness of breath for a few days, and my chest feels tight. I’ve been wheezing a lot, and it’s hard to catch my breath."
    },
    {
      "turn_number": 3,
      "time": "2173-04-27 02:04:00",
      "speaker": "Doctor",
      "text": "I see you have asthma. Were you using your inhaler more than usual?"
    },
    {
      "turn_number": 4,
      "time": "2173-04-27 02:05:00",
      "speaker": "Patient",
      "text": "Yes, I’ve been using it every few hours. It helps a little, but not like before."
    },
    {
      "turn_number": 5,
      "time": "2173-04-27 02:07:00",
      "speaker": "Doctor",
      "text": "We also noticed you were very sleepy when you came in. Are you feeling more alert now?"
    },
    {
      "turn_number": 6,
      "time": "2173-04-27 02:08:00",
      "speaker": "Patient",
      "text": "A little. I was so tired last night. I couldn’t sleep well because of the breathing."
    },
    {
      "turn_number": 7,
      "time": "2173-04-27 02:10:00",
      "speaker": "Doctor",
      "text": "Your oxygen level was low, around 88%, but it improved with oxygen. We gave you breathing treatments and steroids in the ER. We’re watching you closely."
    },
    {
      "turn_number": 8,
      "time": "2173-04-27 02:12:00",
      "speaker": "Patient",
      "text": "I’m scared. Is it my asthma again? I was just in the hospital a month ago."
    },
    {
      "turn_number": 9,
      "time": "2173-04-27 02:14:00",
      "speaker": "Doctor",
      "text": "Yes, it looks like an asthma flare-up. But we also think your heart failure might be playing a role. Your lungs are working hard, and your legs are swollen."
    },
    {
      "turn_number": 10,
      "time": "2173-04-27 02:16:00",
      "speaker": "Patient",
      "text": "My legs have been hurting and swollen. But I didn’t think it was serious."
    },
    {
      "turn_number": 11,
      "time": "2173-04-27 02:18:00",
      "speaker": "Doctor",
      "text": "We gave you a strong diuretic, lasix, through your IV. That should help reduce the fluid and ease your breathing."
    },
    {
      "turn_number": 12,
      "time": "2173-04-27 02:20:00",
      "speaker": "Patient",
      "text": "Okay. But I don’t want to take too much lasix at home. It makes me go to the bathroom a lot, and I can’t get there fast enough."
    },
    {
      "turn_number": 13,
      "time": "2173-04-27 02:22:00",
      "speaker": "Doctor",
      "text": "I understand. But if we don’t manage the fluid, your breathing will get worse. We’ll work with your doctor to find a balance."
    },
    {
      "turn_number": 14,
      "time": "2173-04-27 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs show your white blood cell count was high, but it’s coming down. Your breathing treatment is helping."
    },
    {
      "turn_number": 15,
      "time": "2173-04-27 08:02:00",
      "speaker": "Patient",
      "text": "That’s good. What about the urine test? They said something was in it."
    },
    {
      "turn_number": 16,
      "time": "2173-04-27 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, your urine showed signs of infection. The culture grew E. coli, but you’re not having symptoms like burning or urgency."
    },
    {
      "turn_number": 17,
      "time": "2173-04-27 08:06:00",
      "speaker": "Patient",
      "text": "So do I need antibiotics?"
    },
    {
      "turn_number": 18,
      "time": "2173-04-27 08:08:00",
      "speaker": "Doctor",
      "text": "Not right now. Since you’re not symptomatic, we’ll let your primary doctor decide after reviewing the results."
    },
    {
      "turn_number": 19,
      "time": "2173-04-27 08:10:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense."
    },
    {
      "turn_number": 20,
      "time": "2173-04-27 14:00:00",
      "speaker": "Doctor",
      "text": "We checked for viruses, and your respiratory panel was negative. No flu or RSV. That’s good news."
    },
    {
      "turn_number": 21,
      "time": "2173-04-27 14:02:00",
      "speaker": "Patient",
      "text": "So it’s not contagious?"
    },
    {
      "turn_number": 22,
      "time": "2173-04-27 14:04:00",
      "speaker": "Doctor",
      "text": "Not from a virus. Your flare-up is likely due to your asthma and heart failure, not an infection we can spread."
    },
    {
      "turn_number": 23,
      "time": "2173-04-27 14:06:00",
      "speaker": "Patient",
      "text": "What about my sedation? I felt so out of it when I came in."
    },
    {
      "turn_number": 24,
      "time": "2173-04-27 14:08:00",
      "speaker": "Doctor",
      "text": "We think it was from your pain medications—methadone and Dilaudid. Your CO2 level wasn’t high, so it’s not from breathing trouble."
    },
    {
      "turn_number": 25,
      "time": "2173-04-27 14:10:00",
      "speaker": "Patient",
      "text": "I take them for my back and leg pain. But I don’t want to be so sleepy again."
    },
    {
      "turn_number": 26,
      "time": "2173-04-27 14:12:00",
      "speaker": "Doctor",
      "text": "We’ll keep the doses but watch you closely. Only take Dilaudid if the pain is really bad."
    },
    {
      "turn_number": 27,
      "time": "2173-04-28 09:00:00",
      "speaker": "Doctor",
      "text": "Your breathing is better. Your oxygen is 95% on room air. Your lungs still have some wheezing, but it’s improving."
    },
    {
      "turn_number": 28,
      "time": "2173-04-28 09:02:00",
      "speaker": "Patient",
      "text": "I feel better. Can I go home soon?"
    },
    {
      "turn_number": 29,
      "time": "2173-04-28 09:04:00",
      "speaker": "Doctor",
      "text": "We’re hoping to discharge you tomorrow. But we need to make sure your heart failure is stable and your breathing stays good."
    },
    {
      "turn_number": 30,
      "time": "2173-04-28 09:06:00",
      "speaker": "Patient",
      "text": "I’ve been drinking a lot of fluids. Is that okay?"
    },
    {
      "turn_number": 31,
      "time": "2173-04-28 09:08:00",
      "speaker": "Doctor",
      "text": "Actually, with heart failure, too much fluid can make it harder to breathe. Try to limit to about 64 ounces a day."
    },
    {
      "turn_number": 32,
      "time": "2173-04-28 09:10:00",
      "speaker": "Patient",
      "text": "I didn’t know that. I’ll try."
    },
    {
      "turn_number": 33,
      "time": "2173-04-28 15:00:00",
      "speaker": "Doctor",
      "text": "Your INR was low when you came in. That means your blood wasn’t thin enough. We’ve increased your warfarin dose to 12.5 mg daily."
    },
    {
      "turn_number": 34,
      "time": "2173-04-28 15:02:00",
      "speaker": "Patient",
      "text": "I missed a few doses when I was sick. Should I be worried?"
    },
    {
      "turn_number": 35,
      "time": "2173-04-28 15:04:00",
      "speaker": "Doctor",
      "text": "Just keep taking it daily and follow up with your doctor to check your INR regularly."
    },
    {
      "turn_number": 36,
      "time": "2173-04-28 15:06:00",
      "speaker": "Patient",
      "text": "Okay, I will."
    },
    {
      "turn_number": 37,
      "time": "2173-04-29 10:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re going to discharge you today. You’ll take a short course of prednisone and azithromycin."
    },
    {
      "turn_number": 38,
      "time": "2173-04-29 10:02:00",
      "speaker": "Patient",
      "text": "What about my lasix? I only want to take 40 mg."
    },
    {
      "turn_number": 39,
      "time": "2173-04-29 10:04:00",
      "speaker": "Doctor",
      "text": "We’re prescribing 40 mg daily, but know that skipping higher doses may make your heart failure worse over time."
    },
    {
      "turn_number": 40,
      "time": "2173-04-29 10:06:00",
      "speaker": "Patient",
      "text": "I understand. I’ll do my best."
    },
    {
      "turn_number": 41,
      "time": "2173-04-29 10:08:00",
      "speaker": "Doctor",
      "text": "Also, weigh yourself every morning. Call your doctor if you gain more than 3 pounds in a day."
    },
    {
      "turn_number": 42,
      "time": "2173-04-29 10:10:00",
      "speaker": "Patient",
      "text": "I’ll do that. Thank you for explaining everything."
    },
    {
      "turn_number": 43,
      "time": "2173-04-29 10:12:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and follow up with your primary doctor soon."
    },
    {
      "turn_number": 44,
      "time": "2173-04-29 10:14:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    }
  ],
  "summary": {
    "admission_start": "2173-04-27 01:50:00",
    "admission_end": "2173-04-29 16:35:00",
    "summary_paragraph": "The patient was admitted for worsening shortness of breath, wheezing, and chest pain, consistent with an asthma exacerbation. She was initially somnolent, likely due to sedation from her chronic opioid medications, but remained alert with stable respiratory status. Her hypoxia improved with bronchodilators and steroids. Congestive heart failure was contributing, evidenced by elevated BNP and edema, and she responded to IV lasix. Due to concerns about incontinence, she declined higher oral diuretic doses. A urine culture grew E. coli, but as she was asymptomatic, antibiotics were not started, and follow-up was arranged with her primary care provider. Her warfarin dose was increased due to a subtherapeutic INR. She was discharged home on a prednisone taper, azithromycin, and adjusted medications, with instructions to monitor weight and adhere to fluid and medication regimens.",
    "problems": [
      "Asthma, unspecified type, with (acute) exacerbation",
      "Acute on chronic diastolic heart failure",
      "Urinary tract infection, site not specified",
      "Morbid obesity",
      "Congestive heart failure, unspecified",
      "Long-term (current) use of anticoagulants",
      "Asymptomatic human immunodeficiency virus [HIV] infection status",
      "Hypoxemia",
      "Obstructive sleep apnea (adult)(pediatric)",
      "Depressive disorder, not elsewhere classified",
      "Anxiety state, unspecified",
      "Constipation, unspecified",
      "Altered mental status",
      "Other chronic pain",
      "Backache, unspecified",
      "Pain in limb",
      "Do not resuscitate status"
    ]
  }
}
